    maxk=max(lp,lq)
    nmods=[n%(10**(k+1)) for k in range(maxk)]
    states={(0,0)}
    pow10=1
    for k in range(maxk):
        new=set()
        pdigs=[p_known[k]] if k in p_known else (list(range(10)) if k<lp else [0])
        qdigs=[q_known[k]] if k in q_known else (list(range(10)) if k<lq else [0])
