        if k>=lp: pdigs=[0]
        if k>=lq: qdigs=[0]
        for pmod,qmod in states:
            for a in pdigs:
                if k==lp-1 and a==0: continue
                pnew=pmod + a*pow10
                for b in qdigs:
                    if k==lq-1 and b==0: continue
                    qnew=qmod + b*pow10
