flag_re=re.compile(r'HTB\{[^}]+\}')

def play(seq):
    s=requests.Session()
    for cmd in seq:
        r=s.post(base+'/api/monitor', json={'command':cmd})
        try:
            j=r.json()
        except Exception:
            return None, f'nonjson {r.status_code} {r.text[:120]}'
        msg=j.get('message','')
        m=flag_re.search(msg)
        if m:
            return m.group(0), msg
        if 'Game over' in msg or 'died' in msg:
            return None, msg
    return None, msg

for seq in itertools.product(*steps):
    flag, msg = play(seq)
    if flag:
        print('FOUND', flag)
        print('PATH:', ' -> '.join(seq))
        print('MSG:', msg)
        break
else:
    print('No flag found via straightforward 4-step brute force')
