import socket
import numpy as np
from hashlib import sha256
from Crypto.Cipher import AES
from Crypto.Util.number import long_to_bytes, bytes_to_long
import re

def getCRC16(msg, gen_poly):
    """Exact implementation from challenge"""
    msglen = msg.bit_length()
    msg <<= 16
    for i in range(msglen - 1, -1, -1):
        if (msg >> (i + 16)) & 1:
            msg ^= (gen_poly << i)
    return msg

class GF2Solver:
    def __init__(self, n_cols):
        self.n_cols = n_cols
        self.rows = []
        self.pivot_col = {}

    def add_row(self, row, rhs):
        for col in sorted(self.pivot_col.keys()):
            if row[col]:
                row = row ^ self.rows[self.pivot_col[col]][0]
                rhs = rhs ^ self.rows[self.pivot_col[col]][1]

        pivot = None
        for i in range(self.n_cols):
            if row[i]:
                pivot = i
                break

        if pivot is None:
            if rhs:
                return False
            return True

        row_idx = len(self.rows)
        self.rows.append((row, rhs))
        self.pivot_col[pivot] = row_idx

        for i, (r, b) in enumerate(self.rows[:-1]):
            if r[pivot]:
                self.rows[i] = (r ^ row, b ^ rhs)

        return True

    def get_solution(self):
        x = np.zeros(self.n_cols, dtype=np.uint8)
        for col, row_idx in self.pivot_col.items():
            x[col] = self.rows[row_idx][1]
        return x

    def copy(self):
        new = GF2Solver(self.n_cols)
        new.rows = [(r.copy(), b) for r, b in self.rows]
        new.pivot_col = self.pivot_col.copy()
        return new


def solve_crc_problem(equations, key_bits=512):
    n_queries = len(equations)

    coeff_cache = {}
    for poly, _ in equations:
        coeffs = np.zeros((16, key_bits), dtype=np.uint8)
        for i in range(key_bits):
            crc_val = getCRC16(1 << i, poly)
            for j in range(16):
                coeffs[j, i] = (crc_val >> j) & 1
        coeff_cache[poly] = coeffs

    max_initial = min(10, n_queries)

    best_key = None
    best_consistency = 0

    for combo in range(3**max_initial):
        choices = []
        temp = combo
        for _ in range(max_initial):
            choices.append(temp % 3)
            temp //= 3

        solver = GF2Solver(key_bits)
        consistent = True

        for idx, choice in enumerate(choices):
            poly, values = equations[idx]
            coeffs = coeff_cache[poly]
            crc_val = values[choice]

            for j in range(16):
                row = coeffs[j].copy()
                rhs = (crc_val >> j) & 1
                if not solver.add_row(row, rhs):
                    consistent = False
                    break

            if not consistent:
                break

        if consistent:
            for idx in range(max_initial, n_queries):
                poly, values = equations[idx]
