# returns solution as 512-bit int if unique, else one solution (free vars=0)
def solve_gf2(eqs, nvars=512):
    eqs = [(m,r) for m,r in eqs if m!=0 or r==0]
    # if m==0 and r==1 => inconsistent
    for m,r in eqs:
