def rank_for_poly(gen_poly, nbits=512):
    basis=[0]*16
    rk=0
    for j in range(nbits):
        v=getCRC16_int(1<<j, gen_poly)
        x=v
        for b in range(15,-1,-1):
            if (x>>b)&1:
                if basis[b]:
                    x^=basis[b]
                else:
                    basis[b]=x
                    rk+=1
                    break
    return rk

def sample_ranks(k, trials=200):
    # construct polys with lowest k bits zero (divisible by x^k)
    res={}
    for _ in range(trials):
        mid = random.getrandbits(16-k)  # bits for exponents k..15
        gp = (1<<16) | (mid<<k)
        rk=rank_for_poly(gp)
        res[rk]=res.get(rk,0)+1
    return sorted(res.items())

