        x=v
        for b in range(15,-1,-1):
            if (x>>b)&1:
                if basis[b]:
                    x ^= basis[b]
                else:
                    basis[b]=x
                    break
    return [basis[b] for b in range(16) if basis[b]]

def in_span(y, basis):
    x=y
    piv={v.bit_length()-1:v for v in basis}
    for b in sorted(piv.keys(), reverse=True):
        if (x>>b)&1:
            x ^= piv[b]
    return x==0

def rows_from_cols(cols):
    rowmask=[0]*16
    for j,c in enumerate(cols):
        cc=c
        while cc:
            lsb = cc & -cc
            bit = lsb.bit_length()-1
            rowmask[bit] |= (1<<j)
            cc ^= lsb
    return rowmask

def solve_gf2(eqs, nvars=512):
    piv={}
    for mask,rhs in eqs:
        m=mask
        r=rhs
        while m:
            b=m.bit_length()-1
            if b in piv:
                m ^= piv[b][0]
                r ^= piv[b][1]
            else:
                piv[b]=(m,r)
                break
        else:
            if r:
                return None
    sol=0
    for b in sorted(piv.keys()):
        m,r=piv[b]
        rest=m & ~(1<<b)
        val = r ^ ((rest & sol).bit_count() & 1)
        if val:
            sol |= (1<<b)
    return sol, (len(piv)==nvars), len(piv)

def oracle(secret, gen_poly):
    res=[secrets.randbits(16) for _ in range(3)]
    res[secrets.randbelow(3)]=getCRC16_int(secret, gen_poly)
