                    x ^= basis[b]
                else:
                    basis[b]=x
                    break
    return [basis[b] for b in range(16) if basis[b]]

def in_span(y, basis):
    x=y
    # basis vectors are 16-bit ints. reduce by pivot bits.
    piv={v.bit_length()-1:v for v in basis}
    for b in sorted(piv.keys(), reverse=True):
        if (x>>b)&1:
            x ^= piv[b]
    return x==0

def rows_from_cols(cols):
    rowmask=[0]*16
    for j,c in enumerate(cols):
        cc=c
        while cc:
            lsb = cc & -cc
            bit = lsb.bit_length()-1
            rowmask[bit] |= (1<<j)
            cc ^= lsb
    return rowmask

class LinSysGF2:
    def __init__(self, nvars=NBITS):
        self.nvars=nvars
        self.piv={}  # pivot_bit -> (mask,rhs)

    def add_eq(self, mask, rhs):
        m=mask
        r=rhs
        while m:
            b=m.bit_length()-1
            if b in self.piv:
                pm,pr = self.piv[b]
                m ^= pm
                r ^= pr
            else:
                self.piv[b]=(m,r)
                return True
        # m==0
        return (r==0)

    @property
    def rank(self):
        return len(self.piv)

    def solve_one(self):
        # assumes consistent. returns solution with free vars set to 0
        sol=0
        for b in sorted(self.piv.keys()):
            m,r = self.piv[b]
            rest = m & ~(1<<b)
            val = r ^ ((rest & sol).bit_count() & 1)
            if val:
                sol |= (1<<b)
        return sol


def gen_candidate_polys():
    polys=[]
    # min exponent >=8 (divisible by x^8): gp=2^16 + (mid<<8)
    for mid in range(1,256):
        polys.append((1<<16)|(mid<<8))
    # min exponent exactly 7 (multiple of x^7 but not x^8): gp=2^16 + (odd<<7)
    for mid in range(1,256,2):
        polys.append((1<<16)|(mid<<7))
    return polys


def precompute():
    items=[]
    for gp in gen_candidate_polys():
        cols = crc_columns(gp)
        basis = span_basis_16(cols)
        rk = len(basis)
        if rk==0 or rk>10:
            continue
        rows = rows_from_cols(cols)
        items.append((gp, basis, rows, rk))
    # sort by rk ascending -> strongest discrimination first, but still enough info
    items.sort(key=lambda t:t[3])
    return items


def recv_until(sock, token: bytes):
    data=b''
    while token not in data:
        chunk=sock.recv(4096)
        if not chunk:
            break
        data += chunk
    return data


def main():
    items = precompute()

    s = socket.create_connection((HOST,PORT), timeout=10)
    banner = recv_until(s, b'Give me your generator polynomial: ')
    text = banner.decode(errors='replace')
    # parse encrypted flag
    # example: "Encrypted flag: <hex>\nGive me..."
    enc_hex = None
    for line in text.splitlines():
        if line.startswith('Encrypted flag:'):
            enc_hex = line.split(':',1)[1].strip()
            break
    if not enc_hex:
        raise RuntimeError('could not parse encrypted flag banner')
    enc_flag = bytes.fromhex(enc_hex)

    sys = LinSysGF2(NBITS)
    used=0
    skipped_amb=0
    for gp,basis,rows,rk in items:
        # send polynomial
        s.sendall(f"{gp}\n".encode())
        out = recv_until(s, b'Give me your generator polynomial: ')
        # response line contains list
        out_text = out.decode(errors='replace')
        # pick last bracketed thing
        start = out_text.find('[')
        end = out_text.find(']')
        if start==-1 or end==-1:
            raise RuntimeError('unexpected oracle output: '+out_text)
        arr = ast.literal_eval(out_text[start:end+1])
        candidates=[y for y in arr if in_span(y,basis)]
        if len(candidates)!=1:
            skipped_amb += 1
            continue
        rem = candidates[0]
        # add 16 equations
        ok=True
        for b in range(16):
            if not sys.add_eq(rows[b], (rem>>b)&1):
                ok=False
                break
        if not ok:
            raise RuntimeError('inconsistency encountered (should not happen)')

        used += 1
        if sys.rank == NBITS:
            break

    if sys.rank != NBITS:
        raise RuntimeError(f'failed to reach full rank: {sys.rank}')

    key = sys.solve_one()

    aes_key = sha256(long_to_bytes(key)).digest()[:16]
    cipher = AES.new(aes_key, AES.MODE_CTR, nonce=b"12345678")
    flag = cipher.decrypt(enc_flag)
    print(flag)

if __name__=='__main__':
    main()
