def simulate_game(moves_input):
    _map = [
        ["#", "#", "#", "#", "#", "#", "#", "#", "#", "#"],
        ["#", "S", "X", "#", " ", " ", " ", " ", "#", "#"],
        ["#", " ", "X", "#", " ", " ", " ", " ", "#", "#"],
        ["#", " ", "X", "#", "X", "X", "X", " ", "#", "#"],
        ["#", " ", " ", "#", "P", " ", "X", "X", "#", "#"],
        ["#", "#", " ", "W", "W", " ", "X", "X", "#", "#"],
        ["#", "X", " ", "M", " ", " ", " ", "X", "W", "#"],
        ["#", "W", "W", "W", "W", "X", " ", " ", "W", "F"],  # F at (7,9)
        ["#", "X", "X", "X", "X", "X", "X", "X", "W", "#"],
        ["#", "#", "#", "#", "#", "#", "#", "#", "#", "#"],
    ]

    x, y = 1, 1
    monsterHp = 3
    hasPickaxe = False
    movesNeeded = 0
    canPickupPickaxe = False
    isBraced = False
    done_moves = ""

    def checkMove(x, y, dir):
        nonlocal movesNeeded
        if movesNeeded > 0:
            movesNeeded -= 1
            return False
        if dir == 0:  # up
            if _map[x-1][y] in ["#", "M", "W"]:
                return False
        elif dir == 1:  # right
            if _map[x][y+1] in ["#", "M", "W"]:
                return False
        elif dir == 2:  # down
            if _map[x+1][y] in ["#", "M", "W"]:
                return False
        elif dir == 3:  # left
            if _map[x][y-1] in ["#", "M", "W"]:
                return False
        return True

    def do_move(dir, move_name):
        nonlocal x, y, movesNeeded, canPickupPickaxe, done_moves
        if move_name:
            done_moves += move_name
        if not checkMove(x, y, dir):
            return False, False
        if dir == 0: nx, ny = x-1, y
        elif dir == 1: nx, ny = x, y+1
        elif dir == 2: nx, ny = x+1, y
        elif dir == 3: nx, ny = x, y-1
        if _map[nx][ny] == "X":
            movesNeeded = 1
        if _map[nx][ny] == "F":
            return True, True  # Win!
        if canPickupPickaxe:
            canPickupPickaxe = False
        if _map[nx][ny] == "P":
            canPickupPickaxe = True
        _map[x][y] = " "
        _map[nx][ny] = "S"
        x, y = nx, ny
        return True, False

    for move_cmd in moves_input:
        if move_cmd == "up":
            ok, won = do_move(0, "up")
        elif move_cmd == "right":
            ok, won = do_move(1, "right")
        elif move_cmd == "down":
            ok, won = do_move(2, "down")
        elif move_cmd == "left":
            ok, won = do_move(3, "left")
        elif move_cmd == "brace":
            done_moves += "brace"
            if _map[x-1][y] == "M" or _map[x+1][y] == "M" or _map[x][y-1] == "M" or _map[x][y+1] == "M":
                isBraced = True
        elif move_cmd == "fight":
            done_moves += "fight"
            if _map[x-1][y] == "M" or _map[x+1][y] == "M" or _map[x][y-1] == "M" or _map[x][y+1] == "M":
                monsterHp -= 1
                if monsterHp == 0:
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        if _map[x+dx][y+dy] == "M":
                            _map[x+dx][y+dy] = " "
                if not isBraced:
                    do_move(3, "")  # knockback left
        elif move_cmd == "pickup":
            done_moves += "pickup"
            if canPickupPickaxe:
                hasPickaxe = True
                canPickupPickaxe = False
        elif move_cmd == "mine":
            done_moves += "mine"
            if hasPickaxe:
                for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                    if _map[x+dx][y+dy] == "W":
                        _map[x+dx][y+dy] = " "

        print(f"{move_cmd}: pos=({x},{y}), _map[7][8]={_map[7][8]}, _map[7][9]={_map[7][9]}")

        if won:
