]
monsterHp=3
hasPickaxe=False
movesNeeded=0
canPickupPickaxe=False
isBraced=False
x,y=1,1

DIR={'up':0,'right':1,'down':2,'left':3}

def tile(nx,ny):
    return _map[nx][ny]

def checkMove(x,y,dir):
    global movesNeeded
    if movesNeeded>0:
        movesNeeded-=1
        return False
    nx,ny=x,y
    if dir==0: nx-=1
    if dir==1: ny+=1
    if dir==2: nx+=1
    if dir==3: ny-=1
    t=tile(nx,ny)
    if t in ['#','M','W']:
        return False
    return True

def move(x,y,dir):
    global movesNeeded, canPickupPickaxe
    if checkMove(x,y,dir):
        nx,ny=x,y
        if dir==0: nx-=1
        if dir==1: ny+=1
        if dir==2: nx+=1
        if dir==3: ny-=1
        t=tile(nx,ny)
        if t=='X':
            movesNeeded=1
        if t=='F':
            return nx,ny,'WIN'
        if canPickupPickaxe:
            canPickupPickaxe=False
        if t=='P':
            canPickupPickaxe=True
        _map[x][y]=' '
        _map[nx][ny]='S'
        return nx,ny,None
    return x,y,None

cmds=['down','down','down','right','down','down','brace','fight','fight','fight','right','right','right','up','up','left','pickup','right','down','down','right','down','right','mine','right']

for step,c in enumerate(cmds,1):
    if c in DIR:
        ox,oy=x,y
        x,y,status=move(x,y,DIR[c])
        print(step,c,(ox,oy),'->',(x,y),'movesNeeded',movesNeeded,'canPickup',canPickupPickaxe,'status',status)
        if status=='WIN':
            break
    elif c=='pickup':
        if canPickupPickaxe:
            hasPickaxe=True
            canPickupPickaxe=False
        print(step,c,'hasPickaxe',hasPickaxe)
    elif c=='mine':
        if hasPickaxe:
            for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                if tile(x+dx,y+dy)=='W':
                    _map[x+dx][y+dy]=' '
        print(step,c,'mined around',x,y)
    elif c=='brace':
        if any(tile(x+dx,y+dy)=='M' for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]):
            isBraced=True
        print(step,c,'isBraced',isBraced)
    elif c=='fight':
        if any(tile(x+dx,y+dy)=='M' for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]):
            monsterHp-=1
            if monsterHp==0:
                for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    if tile(x+dx,y+dy)=='M':
                        _map[x+dx][y+dy]=' '
            if not isBraced:
                x,y,_=move(x,y,DIR['left'])
        print(step,c,'monsterHp',monsterHp,'pos',(x,y))

print('end pos',x,y,'hasPickaxe',hasPickaxe,'monsterHp',monsterHp,'movesNeeded',movesNeeded)
for r in _map:
    print(''.join(r))
", "timeout": 120}

