cmds=['up','right','down','left','mine','brace','fight','pickup']

def ser_map(m):
    return ''.join(''.join(r) for r in m)

def des_map(s):
    m=[]
    it=iter(s)
    for i in range(10):
        m.append([next(it) for _ in range(10)])
    return m

def checkMove(m,x,y,dir,movesNeeded):
    if movesNeeded>0:
        return False,movesNeeded-1
    dx,dy=[(-1,0),(0,1),(1,0),(0,-1)][dir]
    t=m[x+dx][y+dy]
    if t in '#MW':
        return False,movesNeeded
    return True,movesNeeded


def do_cmd(state,cmd):
    x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,mstr=state
    m=des_map(mstr)
    won=False
    # move cmds
    if cmd in ['up','right','down','left']:
        dir={'up':0,'right':1,'down':2,'left':3}[cmd]
        ok,newMN=checkMove(m,x,y,dir,movesNeeded)
        movesNeeded=newMN
        if ok:
            dx,dy=[(-1,0),(0,1),(1,0),(0,-1)][dir]
            tx,ty=x+dx,y+dy
            t=m[tx][ty]
            if t=='X':
                movesNeeded=1
            if t=='F':
                won=True
            if canPickup:
                canPickup=False
            if t=='P':
                canPickup=True
            m[x][y]=' '
            m[tx][ty]='S'
            x,y=tx,ty
        return (x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,ser_map(m)),won
    if cmd=='mine':
        if hasPickaxe:
            for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                if m[x+dx][y+dy]=='W':
                    m[x+dx][y+dy]=' '
        return (x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,ser_map(m)),won
    if cmd=='brace':
        if any(m[x+dx][y+dy]=='M' for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]):
            isBraced=True
        return (x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,ser_map(m)),won
    if cmd=='fight':
        if any(m[x+dx][y+dy]=='M' for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]):
            monsterHp-=1
            if monsterHp==0:
                for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    if m[x+dx][y+dy]=='M':
                        m[x+dx][y+dy]=' '
            if not isBraced:
                # knockback left via move()
                ok,newMN=checkMove(m,x,y,3,movesNeeded)
                movesNeeded=newMN
                if ok:
                    tx,ty=x,y-1
                    t=m[tx][ty]
                    if t=='X':
                        movesNeeded=1
                    if t=='F':
                        won=True
                    if canPickup:
                        canPickup=False
                    if t=='P':
                        canPickup=True
                    m[x][y]=' '
                    m[tx][ty]='S'
                    x,y=tx,ty
        return (x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,ser_map(m)),won
    if cmd=='pickup':
        if canPickup:
            hasPickaxe=True
            canPickup=False
        return (x,y,monsterHp,hasPickaxe,movesNeeded,canPickup,isBraced,ser_map(m)),won
    raise

init=(1,1,3,False,0,False,False,ser_map(orig_map))
q=deque([(init,[])])
seen={init}
sol=None
maxdepth=60
while q:
    st,path=q.popleft()
    if len(path)>=maxdepth: continue
    for c in cmds:
        nst,won=do_cmd(st,c)
        npath=path+[c]
        if won:
            sol=npath
            q.clear();break
        if nst not in seen:
            seen.add(nst)
            q.append((nst,npath))
    if sol: break

print('seen',len(seen))
print('sol_len',len(sol) if sol else None)
print('sol',sol)
print('concat',''.join(sol) if sol else None)
