import requests
import concurrent.futures

def check_url(url):
    try:
        response = requests.get(url, timeout=2, allow_redirects=False)
        if response.status_code in [200, 301, 302, 401, 403]:
            return (url, response.status_code, response.text[:200])
    except:
        pass
    return None

# Common picoCTF instance patterns
base_patterns = [
    "http://{}-citadel.picoctf.net:52137",
    "http://{}-fortress.picoctf.net:57453",
    "http://{}-tower.picoctf.net:63398",
]

# Common prefixes
prefixes = ["amiable", "gentle", "happy", "jolly", "kind", "merry", "nice", "peaceful", "quiet", "silly"]

urls_to_check = []
for prefix in prefixes:
    for pattern in base_patterns:
        urls_to_check.append(pattern.format(prefix))

# Add some common port variations
for prefix in ["amiable", "gentle"]:
    for port in range(50000, 60000, 1000):
        urls_to_check.append(f"http://{prefix}-citadel.picoctf.net:{port}/")

# Also try mercury with various ports
for port in [5000, 5001, 5002, 5003, 5004, 5005, 57453, 52137, 63398]:
    urls_to_check.append(f"http://mercury.picoctf.net:{port}/")
    urls_to_check.append(f"http://saturn.picoctf.net:{port}/")

print(f"Checking {len(urls_to_check)} URLs...")

with concurrent.futures.ThreadPoolExecutor(max_workers=20) as executor:
    futures = {executor.submit(check_url, url): url for url in urls_to_check}
