{"command": "cd /tmp && python3 << 'EOF'
import base64

with open('dns_unique_ordered.txt', 'r') as f:
    subdomains = [line.strip() for line in f]

# The ASCII-decodable parts that make sense
flag_parts = []

for i, sd in enumerate(subdomains):
    try:
        padded = sd + '=' * (4 - len(sd) % 4) if len(sd) % 4 != 0 else sd
        decoded = base64.b64decode(padded)
        if all(32 <= b < 127 or b in [10, 13] for b in decoded):
            text = decoded.decode('ascii')
            # Skip the suspicious ones
            if i not in [81, 173]:
                flag_parts.append((i, text))
                print(f"Part at index {i}: {text}")
    except:
        pass

# Construct the flag
flag = ''.join([part[1] for part in flag_parts])
print(f"\nConstructed flag: {flag}")

# Let me also try looking for specific patterns
print("\n\nSearching for complete flag pattern...")
full_data = b''
for sd in subdomains:
    try:
        padded = sd + '=' * (4 - len(sd) % 4) if len(sd) % 4 != 0 else sd
        decoded = base64.b64decode(padded)
        full_data += decoded
    except:
        pass

# Search for the flag in the concatenated data
if b'picoCTF{' in full_data:
    start = full_data.find(b'picoCTF{')
    end = full_data.find(b'}', start)
    if end != -1:
        print(f"Found in concatenated data: {full_data[start:end+1]}")
EOF
"}

