import urllib.request
import json

# Try to access picoCTF API
try:
    url = "https://play.picoctf.org/api/challenges/"
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    response = urllib.request.urlopen(req, timeout=10)
    data = json.loads(response.read())

    # Look for the "not crypto" challenge
    for challenge in data.get('results', []):
        if 'not crypto' in challenge.get('name', '').lower():
            print(json.dumps(challenge, indent=2))
            break
    else:
        print("Challenge not found in list")
        print("Available challenges:")
        for challenge in data.get('results', [])[:10]:
            print(f"- {challenge.get('name')}")
except Exception as e:
    print(f"Error: {e}")
"}

